// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for ru-safe-priv and purge: owner-only folder, body redaction, retention
// Flo: tmp dir > lock > read ACL > purge old rows > redact text
// I/O: folders and rows > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const priv = @import("ru-safe-priv.zig"); const data = @import("st-stat-data.zig"); const mock = @import("te-mock-page.zig"); const T = std.testing;
test "body log hides text unless enabled, token keeps the length" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); try T.expectEqualStrings("hello", priv.bodyLog(alo, "hello", true)); const tok = priv.bodyLog(alo, "hello", false); try T.expect(std.mem.find(u8, tok, "hello") == null); try T.expect(std.mem.endsWith(u8, tok, ":5»")); }
test "owner-only folder: Windows ACL lists the owner and no broad groups" { if (builtin.os.tag != .windows) return error.SkipZigTest; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var pbuf: [160]u8 = undefined; const rel = try std.fmt.bufPrint(&pbuf, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); const abs = try mock.absPath(T.allocator, T.io, rel); defer T.allocator.free(abs); const who = try std.process.run(T.allocator, T.io, .{ .argv = &.{"whoami"}, .stdout_limit = .limited(512), .stderr_limit = .limited(512) }); defer T.allocator.free(who.stdout); defer T.allocator.free(who.stderr); const user = std.mem.trim(u8, who.stdout, " \r\n"); try T.expect(user.len > 0); try priv.ownerOnly(T.allocator, T.io, abs, user); const res = try std.process.run(T.allocator, T.io, .{ .argv = &.{ "icacls", abs }, .stdout_limit = .limited(8192), .stderr_limit = .limited(8192) }); defer T.allocator.free(res.stdout); defer T.allocator.free(res.stderr); try T.expect(std.mem.find(u8, res.stdout, "BUILTIN\\Users") == null); try T.expect(std.mem.find(u8, res.stdout, "Everyone") == null); try T.expect(std.mem.find(u8, res.stdout, "(OI)(CI)(F)") != null); }
test "owner-only with an empty user or a missing folder fails" { if (builtin.os.tag == .windows) { try T.expectError(error.Fail, priv.ownerOnly(T.allocator, T.io, "C:\\no-such-za-dir-xyz", "nobody-xyz")); try T.expectError(error.Fail, priv.ownerOnly(T.allocator, T.io, "C:\\Windows", "")); } else { try T.expectError(error.Fail, priv.ownerOnly(T.allocator, T.io, "/no/such/za/dir", "")); } }
test "purge removes only old messages and keeps sends" { var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); const D: i64 = 86400000; try sto.msgAdd("c", "them", "old", 1 * D); try sto.msgAdd("c", "them", "edge", 70 * D); try sto.msgAdd("c", "them", "new", 99 * D); _ = try sto.sendBegin("c", "x", 1); try sto.sendDone("c", "x", 2); try T.expectEqual(@as(u32, 1), try sto.purge(100 * D, 30)); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const left = try sto.msgTail(aren.allocator(), "c", 10); try T.expectEqual(@as(usize, 2), left.len); try T.expectEqualStrings("edge", left[0].body); try T.expect(try sto.sendBegin("c", "x", 3) == .dup); try T.expectEqual(@as(u32, 0), try sto.purge(100 * D, 30)); try T.expectEqual(@as(u32, 0), try sto.purge(100 * D, 0)); }
